import basicSsl from '@vitejs/plugin-basic-ssl';
import { defineConfig, resolveConfig } from 'vite';

// LAN に公開する開発サーバーから配信させたくない、エージェント・ツール用のファイル。
// パターンに `/` を含めると Vite はそのまま glob として使う (含めないと `**/` が前置される)。
const devOnlyDeny = [
  '**/.entire/**',
  '**/.claude/**',
  '**/.codex/**',
  '**/AGENTS.md',
  '**/CLAUDE.md',
];

// `server.fs.deny` を指定すると Vite の既定値 (.env や *.pem、.git など) とは結合されず置き換わる。
// 既定値は公開 API から取れず、Vite の版で増減もするので、設定ファイルを読まずに解決させて
// インストール済み Vite の既定値をそのまま受け取り、そこへ追加する。
async function defaultFsDeny(): Promise<string[]> {
  const resolved = await resolveConfig({ configFile: false, logLevel: 'silent' }, 'serve');
  const deny = resolved.server.fs.deny;
  if (deny.length === 0) {
    throw new Error('Vite の既定の server.fs.deny を取得できなかった');
  }
  return deny;
}

// WebXR は安全なコンテキスト (HTTPS か localhost) でしか使えない。
// Quest から LAN 経由で開けるように、自己署名証明書の HTTPS で全インターフェースに公開する。
export default defineConfig(async () => ({
  plugins: [basicSsl()],
  server: {
    host: true,
    fs: { deny: [...new Set([...(await defaultFsDeny()), ...devOnlyDeny])] },
  },
  preview: { host: true },
  build: { target: 'es2022' },
}));

