const mine = await resolveConfig({ logLevel: 'silent' }, 'serve');
console.log('default deny:', base.server.fs.deny);
console.log('resolved deny:', mine.server.fs.deny);
console.log('defaults kept:', base.server.fs.deny.every((d) => mine.server.fs.deny.includes(d)));
console.log('host:', mine.server.host, 'https:', !!mine.server.https);

const server = await createServer({ logLevel: 'silent', server: { port: 5199, strictPort: true, host: '127.0.0.1' } });
await server.listen();
const paths = ['/', '/src/main.ts', '/.claude/settings.json', '/.claude/settings.json?import', '/.claude/settings.json?raw',
  '/.entire/agent-guide.md', '/.entire/agent-guide.md?raw', '/AGENTS.md', '/CLAUDE.md', '/.git/config', '/.CLAUDE/settings.json',
  '/%2Eclaude/settings.json', `/@fs/${root.replaceAll('\\', '/')}/.claude/settings.json`];
process.env.NODE_TLS_REJECT_UNAUTHORIZED = '0';
for (const p of paths) {
  try {
    const r = await fetch(`https://127.0.0.1:5199${p}`);
    console.log(r.status, p);
  } catch (e) { console.log('ERR', p, e.message); }
}
await server.close();
process.exit(0);

import basicSsl from '@vitejs/plugin-basic-ssl';
import { defineConfig } from 'vite';

// `server.fs.deny` を指定すると、Vite の既定値とは結合されずに置き換わる。
// そのため既定値を自分で書き写して残す。以下は vite@8.3.8 の既定値そのまま。
// Vite を更新したときは、既定値が増減していないかを確認し、この配列を合わせること。
const viteDefaultFsDeny = [
  '.env',
  '.env.*',
  '*.{crt,pem,key,p12,pfx,cer,der}',
  '.npmrc',
  '.yarnrc.yml',
  '**/.git/**',
];

